import{_ as o,C as s,o as t,c as r,a2 as a,b as d,w as i,a as l,E as c,a3 as h}from"./chunks/framework.Bqn-bhhR.js";const _=JSON.parse('{"title":"Query Generation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/query-generation.md","filePath":"guide/query-generation.md","lastUpdated":1786047222000}'),p={name:"guide/query-generation.md"};function u(m,e,g,k,y,b){const n=s("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a('<h1 id="query-generation" tabindex="-1">Query Generation <a class="header-anchor" href="#query-generation" aria-label="Permalink to &quot;Query Generation&quot;">​</a></h1><p>When you bookmark a range, Codemark must produce a tree-sitter query that uniquely identifies that code so it can be found again later — even after the surrounding code changes. This page walks through the real pipeline in <code>crates/codemark-core/src/query/generator.rs</code>.</p><div class="tip custom-block"><p class="custom-block-title">The query is the durable identity</p><p>A bookmark&#39;s query is generated <strong>once</strong> at creation and <strong>never rewritten</strong> after drift. The tiered fallback at resolution time (relax → minimize → hash) is the entire recovery mechanism. The query is the anchor; resolutions are the moving history.</p></div><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2>',4)),(t(),d(h,null,{default:i(()=>[c(n,{id:"mermaid-14",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22byte%2Fline%20range%22%5D%20--%3E%20S%5B%22find_tightest_node%5Cn%2B%20body-descent%22%5D%0A%20%20S%20--%3E%20TGT%5B%22target%20Node%22%5D%0A%20%20TGT%20--%3E%20PATH%5B%22build_structural_path%5Cnroot%20%E2%86%92%20target%5Cn(Vec%3CPathEntry%3E)%22%5D%0A%20%20PATH%20--%3E%20DIS%5B%22disambiguate_query%5Cnname-minimization%5Cnuntil%20exactly%201%20match%22%5D%0A%20%20DIS%20--%3E%20BUILD%5B%22build_tier1_query%5Cnemit%20S-expression%22%5D%0A%20%20BUILD%20--%3E%20Q%5B%22GeneratedQuery%5Cn%7B%20query%2C%20node_type%2C%20name%20%7D%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h2 id="step-1-—-snapping-to-the-target-node" tabindex="-1">Step 1 — Snapping to the target node <a class="header-anchor" href="#step-1-—-snapping-to-the-target-node" aria-label="Permalink to &quot;Step 1 — Snapping to the target node&quot;">​</a></h2><p>There is no &quot;snap up to the enclosing declaration&quot;. Instead, two mechanisms combine:</p><ol><li><strong><code>find_tightest_node</code></strong> — for a point range it finds the deepest named node at the point; for a multi-byte range it finds the smallest named node covering the range. Anonymous nodes (like <code>(</code>) are skipped.</li><li><strong>Body-descent loop</strong> — while the node is a <em>body node</em> (<code>block</code>, <code>declaration_list</code>, <code>class_body</code>, <code>statement_block</code>, …), it descends into the first named child overlapping the range. It stops as soon as a node carries semantic info.</li></ol><p>So a single line inside a method body targets the tightest node (a <code>block</code>), <strong>not</strong> the enclosing <code>function_item</code>. The function still appears in the bookmark — as a <em>landmark ancestor</em> in the structural path, where it gets named.</p><h2 id="landmarks-vs-sticky-captures-—-two-different-things" tabindex="-1">Landmarks vs. sticky captures — two different things <a class="header-anchor" href="#landmarks-vs-sticky-captures-—-two-different-things" aria-label="Permalink to &quot;Landmarks vs. sticky captures — two different things&quot;">​</a></h2><p>These are easy to confuse but are distinct concepts:</p><ul><li><strong>Landmarks</strong> drive <em>query anchoring</em>. <code>is_landmark_kind(kind)</code> is true when a node type is in the language <code>Profile::landmark_kinds</code> (or the <code>DECLARATION_TYPES</code> fallback). Only landmark ancestors are eligible to be named during disambiguation — this is what makes queries stable across refactors.</li><li><strong>Sticky captures</strong> (<code>@sticky.class</code>, <code>@sticky.function</code>) are <em>UI tags</em> emitted on the same nodes that landmarks name. They&#39;re collected at match time to build human-readable breadcrumbs (&quot;in <code>AuthService.validateToken</code>&quot;). They don&#39;t affect anchoring.</li></ul><h2 id="step-2-—-building-the-structural-path" tabindex="-1">Step 2 — Building the structural path <a class="header-anchor" href="#step-2-—-building-the-structural-path" aria-label="Permalink to &quot;Step 2 — Building the structural path&quot;">​</a></h2><p><code>build_structural_path</code> walks from the target up to (excluding) the root, building a <code>Vec&lt;PathEntry&gt;</code> (outermost first):</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>node_type</code></td><td>The tree-sitter kind.</td></tr><tr><td><code>name_info</code></td><td>The node&#39;s name (if it has a nameable field), forced to <code>None</code> on body nodes.</td></tr><tr><td><code>is_landmark</code></td><td>Whether this ancestor is an eligible anchor.</td></tr><tr><td><code>sticky_tag</code></td><td>The <code>@sticky.&lt;category&gt;</code> tag, if any.</td></tr></tbody></table><p>Two rules keep the path clean:</p><ul><li><strong>Wrapper nodes</strong> (<code>export_statement</code>, <code>decorated_definition</code>) are <em>skipped</em> — they have no queryable name.</li><li><strong>Local declarations</strong> inside functions are <em>demoted</em> to non-landmark, so a local variable isn&#39;t mistaken for an anchor.</li></ul><h2 id="step-3-—-disambiguation-the-real-compaction" tabindex="-1">Step 3 — Disambiguation (the real &quot;compaction&quot;) <a class="header-anchor" href="#step-3-—-disambiguation-the-real-compaction" aria-label="Permalink to &quot;Step 3 — Disambiguation (the real &quot;compaction&quot;)&quot;">​</a></h2><p>The query is built from the path, then made unique by a <strong>name-minimization search</strong> in <code>disambiguate_query</code>. It strips <em>all</em> names, keeps only the target&#39;s semantic info, then progressively re-adds names until the compiled query matches exactly <strong>one</strong> node (verified by compiling and running it):</p><ol><li>Name only the target. Accept if exactly 1 match (and a named landmark exists, or depth is 1).</li><li>Walk ancestors; restore each landmark ancestor&#39;s name; accept on first unique match.</li><li>Restore <em>all</em> ancestor names.</li><li>Fully unnamed path.</li><li>Else error <code>AmbiguousQuery</code>.</li></ol><p>So &quot;compaction&quot; really means: <strong>drop names on non-landmark ancestors and keep the fewest named landmarks that still disambiguate.</strong> Body nodes contribute only their type for nesting — never a name.</p><h2 id="step-4-—-emitting-the-query-string" tabindex="-1">Step 4 — Emitting the query string <a class="header-anchor" href="#step-4-—-emitting-the-query-string" aria-label="Permalink to &quot;Step 4 — Emitting the query string&quot;">​</a></h2><p><code>build_tier1_query</code> produces the tree-sitter S-expression. Conventions:</p><ul><li>The target&#39;s name capture is always <code>@fn_name</code>; ancestors are <code>@name0</code>, <code>@name1</code>, …</li><li>Named landmarks additionally get a <code>@sticky.&lt;category&gt;</code> on the same node.</li><li>The target node always gets <code>@target</code> appended.</li><li>Names are enforced with <code>(#eq? @capture &quot;name&quot;)</code> predicates.</li></ul><h3 id="example-a-swift-method-in-a-class" tabindex="-1">Example: a Swift method in a class <a class="header-anchor" href="#example-a-swift-method-in-a-class" aria-label="Permalink to &quot;Example: a Swift method in a class&quot;">​</a></h3><p>For <code>validateToken</code> inside <code>class AuthService</code>, the generator produces:</p><div class="language-scheme vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scheme</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(class_declaration</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: (type_identifier) @name0 @sticky.class</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  (#eq? @name0 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AuthService&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  (class_body</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    (function_declaration</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      name: (simple_identifier) @fn_name @sticky.function</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      (#eq? @fn_name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;validateToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) @target))</span></span></code></pre></div><p>A top-level Rust function with no ancestors is just:</p><div class="language-scheme vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">scheme</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(function_item name: (identifier) @fn_name (#eq? @fn_name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;create_default_auth_service&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) @target</span></span></code></pre></div><h2 id="fine-grained-targets-with-semanticinfo" tabindex="-1">Fine-grained targets with SemanticInfo <a class="header-anchor" href="#fine-grained-targets-with-semanticinfo" aria-label="Permalink to &quot;Fine-grained targets with SemanticInfo&quot;">​</a></h2><p>Statements without a name field — two <code>if</code> statements, two <code>return</code>s — can&#39;t be disambiguated by a name. For these, <code>extract_semantic_info</code> captures distinguishing content:</p><table tabindex="0"><thead><tr><th>Variant</th><th>What it captures</th></tr></thead><tbody><tr><td><code>IfCondition</code></td><td>The condition being tested</td></tr><tr><td><code>CallTarget</code></td><td>The function being called</td></tr><tr><td><code>AssignmentTarget</code></td><td>The variable being assigned</td></tr><tr><td><code>ReturnValue</code></td><td>The value being returned</td></tr></tbody></table><p>These emit field-scoped captures (<code>condition: (_) @cond</code>, etc.) with their own <code>#eq?</code> predicates, so otherwise-identical statements become uniquely targetable.</p><h2 id="degradation-tiers-applied-at-resolution-not-creation" tabindex="-1">Degradation tiers (applied at resolution, not creation) <a class="header-anchor" href="#degradation-tiers-applied-at-resolution-not-creation" aria-label="Permalink to &quot;Degradation tiers (applied at resolution, not creation)&quot;">​</a></h2><p>When a bookmark is re-resolved and the Tier-1 query no longer matches, the resolver degrades it rather than rewriting it:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Operation</th><th>Effect</th></tr></thead><tbody><tr><td>Tier 2 — <code>relax_query</code></td><td>Strips every <code>#eq?</code>/<code>#match?</code> predicate</td><td>Matches by structure only (all methods in a class)</td></tr><tr><td>Tier 3 — <code>minimize_query</code></td><td>Keeps only the innermost <code>@target</code> pattern + its name predicate</td><td>Drops all ancestors</td></tr></tbody></table><p>See <a href="./health-status">Health Status</a> for how these tiers drive bookmark health.</p>`,32))])}const q=o(p,[["render",u]]);export{_ as __pageData,q as default};
